import * as React from "react";
import * as _ from "lodash";
import { ConfirmModal } from "./ConfirmModal";
import { FitAddon } from "xterm-addon-fit";
import { Terminal } from "xterm";
import "xterm/css/xterm.css";
import { ITerminalProps } from "./LazyLoadedTerminal";
import { IProcess } from "../../services/IProcess";

/**
 * The terminal modal is to be launched with a process such that sysconfig can receive secure user input
 * The modal will operate similar to putty where it will only display and write stdout received from the process
 */

interface IState {
	terminalProcessStatus: boolean;
}

class TerminalModal extends React.Component<ITerminalProps, IState> {
	constructor(props: ITerminalProps) {
		super(props);

		this.state = {
			terminalProcessStatus: true,
		};
	}

	public override render() {

		const {
			title,
			confirmAction,
			confirmText,
			command,
			args,
			process,
			...rest } = this.props;

		return (
			<ConfirmModal
				{...rest}
				title={title}
				confirmAction={confirmAction}
				disableConfirmButton={this.state.terminalProcessStatus}
				confirmText={confirmText}
				type={"Terminal"}
			>
				<TerminalComponent
					setStatus={this.setStatus}
					command={command}
					args={args}
					process={process}
				>

				</TerminalComponent>
			</ConfirmModal >
		);
	}

	private setStatus = (status: boolean) => this.setState({ terminalProcessStatus: status });
}

interface XTermProps {
	setStatus: (status: boolean) => void;
	command: string;
	args: string[];
	process: IProcess;
}

class TerminalComponent extends React.Component<XTermProps> {

	private terminalStyle: React.CSSProperties = { height: "100%", width: "100%", padding: "1px" };
	private parentContainerStyle: React.CSSProperties = { height: "40vh", width: "75vh" }
	private fitAddon: FitAddon = new FitAddon();
	constructor(props: XTermProps) {
		super(props);
	}

	public override render() {
		return (
			<div
				style={this.parentContainerStyle}>
				<div id="xterm" style={this.terminalStyle}>
				</div>
			</div>
		);
	}

	public override componentDidMount() {
		const terminal = new Terminal({ convertEol: true });
		terminal.options.cursorBlink = true;
		terminal.loadAddon(this.fitAddon);
		terminal.open(document.getElementById("xterm"));
		this.fitAddon.fit();
		terminal.element.style.padding = "5px";
		terminal.focus();
		this.attachEventListeners(terminal);
		this.enableTerminalTyping(terminal);
	}

	public override componentWillUnmount() {
		this.fitAddon.dispose();
	}

	private enableTerminalTyping(terminal: Terminal) {
		const process = this.props.process;
		terminal.onKey((e: { key: string, domEvent: KeyboardEvent }) => {
			process.stdin.write(e.key);
		});
	}

	private attachEventListeners(terminal: Terminal) {
		const process = this.props.process;
		//event listeners for stdout, stderr, and process
		process.stdout.on("data", (chunk: any) => {
			terminal.write(chunk);
		});

		process.stdout.on("error", (err: Error) => {
			terminal.write(err.message);
		});

		process.stderr.on("data", (data) => {
			terminal.write(data);
		});

		process.stderr.on("error", (error: Error) => {
			terminal.write(error.message);
		});

		process.on("exit", () => {
			terminal.write("\r\n" + "Press Close to continue...");
			this.props.setStatus(false);
		});
	}
}

export = TerminalModal;
